style.css:
/* Pinkify Spotify — spotify.com */

:root {
  --my-pink: #ff69b4; /* swap this for your favourite pink */
}

/* make text pink */
body,
body * {
  color: var(--my-pink) !important;
}

/* keep icons and buttons pink too */
button,
a,
svg {
  color: var(--my-pink) !important;
}
